#!/usr/bin/env python3
"""Write website/changelog.html from release-notes/*.md (B.13).

backend/.venv/bin/python tools/changelog.py          # rewrite the page
backend/.venv/bin/python tools/changelog.py --check  # fail when it is stale
"""

from __future__ import annotations

import argparse
import html
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
NOTES = ROOT / "release-notes"
PAGE = ROOT / "website/changelog.html"
BEGIN, END = (
    "<!-- BEGIN RELEASES (generated by tools/changelog.py) -->",
    "<!-- END RELEASES -->",
)
TITLE = re.compile(r"^# (\d+\.\d+\.\d+) — (\d{4}-\d{2}-\d{2}|unreleased)\s*$")


def inline(text: str) -> str:
    out = html.escape(text, quote=False)
    out = re.sub(r"`([^`]+)`", r"<code>\1</code>", out)
    out = re.sub(r"\*\*([^*]+)\*\*", r"<strong>\1</strong>", out)
    return re.sub(
        r"\[([^\]]+)\]\((https://[^)\s]+|[a-z0-9-]+\.html)\)",
        lambda m: f'<a href="{html.escape(m.group(2))}">{m.group(1)}</a>',
        out,
    )


def render_note(body: list[str]) -> str:
    parts: list[str] = []
    para: list[str] = []
    items: list[str] = []

    def flush() -> None:
        if para:
            parts.append(f"<p>{inline(' '.join(para))}</p>")
            para.clear()
        if items:
            parts.append(
                "<ul>" + "".join(f"<li>{inline(i)}</li>" for i in items) + "</ul>"
            )
            items.clear()

    for raw in body:
        line = raw.rstrip()
        if not line:
            flush()
        elif line.startswith("## "):
            flush()
            parts.append(f"<h3>{inline(line[3:])}</h3>")
        elif line.startswith("- "):
            if para:
                flush()
            items.append(line[2:])
        elif items and raw.startswith("  "):
            items[-1] += " " + line.strip()  # continuation of a list item
        else:
            para.append(line.strip())
    flush()
    return "\n".join(parts)


def releases() -> list[tuple[tuple[int, ...], str, str, list[str]]]:
    found = []
    for path in NOTES.glob("*.md"):
        if path.name == "README.md":
            continue
        lines = path.read_text(encoding="utf-8").splitlines()
        m = TITLE.match(lines[0] if lines else "")
        if not m or path.stem != m.group(1):
            raise SystemExit(
                f"{path}: first line must be '# {path.stem} — YYYY-MM-DD|unreleased'"
            )
        if m.group(2) == "unreleased":
            continue
        version = tuple(int(x) for x in m.group(1).split("."))
        found.append((version, m.group(1), m.group(2), lines[1:]))
    return sorted(found, reverse=True)


def block() -> str:
    found = releases()
    if not found:
        body = "    <p>The first release is coming soon.</p>"
    else:
        body = "\n".join(
            f'    <section aria-labelledby="v{v}">\n      <h2 id="v{v}">{v}'
            f" <small>{day}</small></h2>\n{render_note(lines)}\n    </section>"
            for _, v, day, lines in found
        )
    return f"{BEGIN}\n{body}\n    {END}"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    page = PAGE.read_text(encoding="utf-8")
    start, end = page.index(BEGIN), page.index(END) + len(END)
    wanted = page[:start] + block() + page[end:]
    if args.check:
        if wanted != page:
            print(
                "website/changelog.html is stale: run tools/changelog.py",
                file=sys.stderr,
            )
            return 1
        return 0
    PAGE.write_text(wanted, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
